arguments.command:
PYTHONDONTWRITEBYTECODE=1 python3 -I -c 'import pyarrow.parquet as pq,collections,re,hashlib
paths=["/workspace/data/train.parquet","/workspace/data/aime2024.parquet","/workspace/data/aime2025.parquet"]
rows={p:pq.read_table(p).to_pylist() for p in paths}
suffix=" Please reason step by step, and put your final answer within \\boxed{}.\n"
def q(r): return r["prompt"][0]["content"]
def base(s): return s[:-len(suffix)] if s.endswith(suffix) else s
def norm(s): return re.sub(r"\s+","",base(s)).replace("\\dfrac","\\frac").replace("\\tfrac","\\frac")
tr=rows[paths[0]]; va=rows[paths[1]]+rows[paths[2]]
print("TRAIN METADATA")
for k in ["data_source","ability"]: print(k,collections.Counter(r[k] for r in tr))
print("styles",collections.Counter(r["reward_model"]["style"] for r in tr),"splits",collections.Counter(r["extra_info"]["split"] for r in tr))
print("prompt list lengths",collections.Counter(len(r["prompt"]) for r in tr),"roles",collections.Counter(tuple(m["role"] for m in r["prompt"]) for r in tr))
print("suffixes",collections.Counter(q(r).endswith(suffix) for r in tr+va))
print("index min/max/unique",min(r["extra_info"]["index"] for r in tr),max(r["extra_info"]["index"] for r in tr),len(set(r["extra_info"]["index"] for r in tr)))
print("GT types",collections.Counter(type(r["reward_model"]["ground_truth"]).__name__ for r in tr+va),"GT empty",sum(not r["reward_model"]["ground_truth"] for r in tr+va))
print("TRAIN DUPLICATES exact/base/norm",len(tr)-len(set(q(r) for r in tr)),len(tr)-len(set(base(q(r)) for r in tr)),len(tr)-len(set(norm(q(r)) for r in tr)))
for name,fun in [("exact",q),("base",lambda r:base(q(r))),("norm",lambda r:norm(q(r)))]:
 mp=collections.defaultdict(list)
 for i,r in enumerate(tr):mp[fun(r)].append(i)
 hits=[]
 for j,r in enumerate(va):
  if fun(r) in mp:hits.append((j,mp[fun(r)],r["data_source"],r["reward_model"]["ground_truth"]))
 print("VAL OVERLAP",name,len(hits),hits)
print("GT boxed in train prompt",sum("\\boxed" in q(r) for r in tr),"think in prompts",sum("think" in q(r).lower() for r in tr+va))
print("Answer-like trailing content examples")
for i,r in enumerate(tr):
 if not q(r).endswith(suffix): print(i,repr(q(r)[-300:]))
print("train answer distribution top",collections.Counter(r["reward_model"]["ground_truth"] for r in tr).most_common(20))
print("validation answers",[(r["data_source"],i,r["reward_model"]["ground_truth"]) for i,r in enumerate(va)])'

