import pyarrow.parquet as pq, re
ps=['/workspace/data/train.parquet','/workspace/data/aime2024.parquet','/workspace/data/aime2025.parquet']
def prompt(r): return r['prompt'][0]['content']
def grams(s,n=4):
 t=re.findall(r'[a-z0-9]+',s.lower())
 return set(tuple(t[i:i+n]) for i in range(max(1,len(t)-n+1)))
tr=[(prompt(r),grams(prompt(r))) for r in pq.read_table(ps[0]).to_pylist()]
best=[]
for p in ps[1:]:
 for r in pq.read_table(p).to_pylist():
  q=prompt(r); g=grams(q)
  vals=[]
  for text,h in tr:
   inter=len(g&h)
   vals.append((inter/max(1,min(len(g),len(h))),inter/max(1,len(g|h)),text))
  a=max(vals,key=lambda x:(x[0],x[1]))
  best.append((a[0],a[1],q[:110],a[2][:110]))
for x in sorted(best,reverse=True)[:8]: print('containment/jaccard',round(x[0],3),round(x[1],3),'\n val',x[2],'\n train',x[3])
